<script setup>
import {reactive,ref,watch} from 'vue'
import {onLoad,onShow,onHide,onUnload} from '@dcloudio/uni-app'
import {ownerSession,clearOwnerSession} from '../../services/owner-session.js'
import {operatorSession,operatorToken,clearOperatorSession} from '../../services/operator-session.js'
import {createAsyncDiagnosisApi,initialDiagnosisState,createAsyncDiagnosisFlow,SERVICE_STATES,CASE_STATES,validDiagnosisText} from '../../services/async-diagnosis.js'
import {createDiagnosisRecovery} from '../../services/diagnosis-recovery.js'
import {imageRequestKey} from '../../services/private-images.js'
import {displayTime} from '../../services/reservations.js'
const role=ref(''),id=ref(0),text=ref(''),consent=ref(false),state=reactive(initialDiagnosisState()),api=createAsyncDiagnosisApi(),token=()=>role.value==='owner'?ownerSession.accessToken:role.value==='admin'?operatorToken():'',allowed=()=>role.value==='owner'||role.value==='admin'&&operatorSession.canDiagnose
const recovery=createDiagnosisRecovery({actor:()=>role.value==='owner'?ownerSession.actorId:operatorSession.actorId,role:()=>role.value,scope:()=>`${role.value}:${id.value}`})
const flow=createAsyncDiagnosisFlow({state,token,allowed,recovery,scope:()=>`${role.value}:${id.value}`,newKey:imageRequestKey,load:async(t,p)=>({detail:await api.detail(t,role.value,id.value,p),context:role.value==='owner'?await api.context(t):null}),write:(t,a,n,b,k)=>api.write(t,role.value,a,n,b,k),confirm:action=>new Promise(resolve=>uni.showModal({title:action==='close'?'关闭本次留言':'提交本次文字',content:action==='close'?'关闭后不能继续追加或回复。已有问题和答复仍可按权限查看。确认后原请求保存在本机用于原键恢复。':'本次文字将保存到该诊断记录；车主追加时重新核对当前资格和受理状态。确认后原请求保存在本机用于断线后原键恢复。',success:r=>resolve(r.confirm),fail:()=>resolve(false)})),onWritten:clearForm})
let visible=false;function clearForm(){text.value='';consent.value=false}function reset(){flow.reset();clearForm()}function login(){if(role.value==='owner'){clearOwnerSession();uni.navigateTo({url:'/pages/owner/index'})}else{clearOperatorSession();uni.navigateTo({url:'/pages/operator/login'})}}
function send(){const c=state.data?.detail.case;if(!c||c.status==='CLOSED'||!validDiagnosisText(text.value.trim())){state.message='请核对当前记录并输入1至2000字。';return}const b={expected_revision:c.revision,message:text.value.trim()};if(role.value==='owner'){const ctx=state.data.context;if(!ctx?.eligibility.service_available||!consent.value){state.message='请核对当前资格和受理状态，并确认本次文字用途。';return}Object.assign(b,{policy_id:ctx.service.policy.id,policy_revision:ctx.service.policy.revision,consent:true})}flow.save(role.value==='owner'?'message':'reply',id.value,b)}
function restoreDraft(){const draft=flow.restoreDraft();if(draft){text.value=draft.text;consent.value=false}}
function close(){const c=state.data?.detail.case;if(c&&c.status!=='CLOSED')flow.save('close',id.value,{expected_revision:c.revision})}
watch(()=>[token(),allowed(),role.value,id.value],()=>{reset();if(visible&&token()&&allowed())flow.load()},{flush:'sync'})
onLoad(q=>{role.value=['owner','admin'].includes(q?.role)?q.role:'';id.value=/^[1-9]\d*$/.test(String(q?.id||''))?Number(q.id):0});onShow(()=>{visible=true;if(token()&&allowed())flow.load()});onHide(()=>{visible=false;reset()});onUnload(()=>{visible=false;reset()})
watch(()=>state.kind,k=>{if(['unauthorized','forbidden','missing'].includes(k)){clearForm()}})
</script>
<template><view class="reservation-page"><text class="reservation-title">诊断留言与答复</text><text>非实时服务；仅本人与当前获派且有处理权限的诊断人员可读正文。</text><text v-if="!allowed()">此入口需要车主身份或独立诊断处理权限及当前分配。</text><button v-if="!token()&&role" @tap="login">登录当前身份</button><text v-if="state.busy">正在核对当前权限…</text><text v-if="state.message">{{state.message}}</text><button v-if="['unauthorized','forbidden'].includes(state.kind)" @tap="login">重新登录</button><button v-if="state.retry" :disabled="state.busy" @tap="flow.retry">重试原操作</button><button :disabled="state.busy" @tap="flow.load(state.page)">刷新</button><template v-if="state.data"><view class="reservation-panel"><text>{{CASE_STATES[state.data.detail.case.status]}}</text><text>{{state.data.detail.vehicle.brand||'品牌未知'}} {{state.data.detail.vehicle.series||'车系未知'}} {{state.data.detail.vehicle.year||'年款未知'}} {{state.data.detail.vehicle.config_name||''}}</text></view><view v-for="m in state.data.detail.messages.items" :key="m.message_id" class="reservation-panel"><text>{{m.sender==='OWNER'?'车主留言':'诊断答复'}} · {{displayTime(m.created_at)}}</text><text class="message-body">{{m.body}}</text></view><button v-if="state.page>1" :disabled="state.busy" @tap="flow.load(state.page-1)">上一页文字</button><button v-if="state.page*20<state.data.detail.messages.total" :disabled="state.busy" @tap="flow.load(state.page+1)">下一页文字</button><template v-if="state.data.detail.case.status!=='CLOSED'"><text v-if="role==='owner'">{{SERVICE_STATES[state.data.context.service.state]}}</text><template v-if="role==='owner'?state.data.context.eligibility.service_available:state.data.detail.case.status==='PROCESSING'"><text>草稿仅保存在当前设备；共享设备使用后请清除。</text><button :disabled="state.busy||state.retry" @tap="flow.saveDraft({text,vehicle:0})">保存本机草稿</button><button v-if="state.hasDraft" :disabled="state.busy||state.retry" @tap="restoreDraft">恢复本机草稿</button><button v-if="state.hasDraft" :disabled="state.busy" @tap="flow.clearDraft">清除本机草稿</button><textarea v-model="text" maxlength="4000" :disabled="state.busy||state.retry" :placeholder="role==='owner'?'追加本次问题':'填写本次答复'"/><checkbox-group v-if="role==='owner'" @change="consent=$event.detail.value.includes('yes')"><label><checkbox value="yes" :checked="consent" :disabled="state.busy||state.retry"/>确认本次文字用于人工诊断</label></checkbox-group><button :disabled="state.busy||state.retry" @tap="send">{{role==='owner'?'追加留言':'提交答复'}}</button></template><button :disabled="state.busy||state.retry" @tap="close">关闭本次留言</button></template></template></view></template>
<style scoped>.message-body{white-space:pre-wrap}</style>
